DEST.mkdir(parents=True,exist_ok=True)
items=[('Caw','crow_rocky',41.50,1.45,'https://home.nps.gov/romo/learn/photosmultimedia/sounds-americancrow.htm','J. Job / National Park Service / Rocky Mountain National Park'),('Raven','raven_grand_teton',.32,1.95,'https://www.nps.gov/media/video/view.htm?id=27990F1A-563F-455D-A2AE-91AFA23C6C0D','National Park Service / Grand Teton National Park')]
