lines=['// Generated by Tools/calder/prepare_corvid_recordings.py. Public domain NPS recordings.','// Owner authorized the recorded-call exception and requested longer natural bursts.','// Attribution and unmodified masters: SourceArt/CalderLandscape/phase3/audio/nps_corvids.','namespace HouseCalderCorvidRecordingData','{']
for name,master,start,length,url,credit in items:
 for suffix in ['.html','.mp3','.wav']:shutil.copyfile(PROPOSAL/(master+suffix),DEST/(master+suffix))
 with wave.open(str(PROPOSAL/(master+'.wav'))) as f:rate=f.getframerate();v=np.frombuffer(f.readframes(f.getnframes()),dtype='<i2').astype(np.float64)/32768.
 v=v[round(start*rate):round((start+length)*rate)];v-=v.mean();fade=round(rate*.012);v[:fade]*=np.linspace(0,1,fade);v[-fade:]*=np.linspace(1,0,fade);v*=.62/max(abs(v));pcm=np.round(v*32767).astype('<i2')
 target=DEST/('CrowCaw.wav' if name=='Caw' else 'RavenCroak.wav')
 with wave.open(str(target),'wb') as f:f.setnchannels(1);f.setsampwidth(2);f.setframerate(rate);f.writeframes(pcm.tobytes())
 lines.append('constexpr int16 '+name+'[]={')
 lines.extend(','.join(str(int(x)) for x in pcm[i:i+32])+',' for i in range(0,len(pcm),32));lines.append('};')
 if name=='Caw':
  # Source-derived10ms RMS; silence between the four caws closes the beak.
  hop=rate//100;env=np.array([np.sqrt(np.mean(v[i:i+hop]**2)) for i in range(0,len(v),hop)]);env=np.clip((env/max(env)-.09)/.55,0,1)
  lines.append('constexpr float CawMouth[]={'+','.join(f'{x:.5f}f' for x in env)+'};')
 manifest['items'].append({'name':name,'source_page':url,'credit':credit,'master_mp3_sha256':hashlib.sha256((DEST/(master+'.mp3')).read_bytes()).hexdigest(),'cut_seconds':[start,start+length],'rate':rate,'samples':len(pcm),'seconds':len(pcm)/rate,'wav_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'pcm_sha256':hashlib.sha256(pcm.tobytes()).hexdigest(),'processing':'crop; DC removal;12ms edge fades; peak normalize -4.15dBFS. No pitch shift or time stretch.','beak_envelope':'actual source10ms RMS' if name=='Caw' else None})
lines.append('}')
generated=ROOT/'Source/SeniorSendoff/HouseCalderCorvidRecordingData.inl';data='\n'.join(lines)+'\n'
