manifest['generated_sha256']=hashlib.sha256(data.encode()).hexdigest();manifest['source_installed']=not args.prepare_only
(DEST/'license_and_processing.json').write_text(json.dumps(manifest,indent=2)+'\n')
(DEST/'CREDITS.txt').write_text('Crow: J. Job / National Park Service, Rocky Mountain National Park.\nRaven: National Park Service, Grand Teton National Park.\nPublic domain recordings.\n'+license_url+'\n'+items[0][4]+'\n'+items[1][4]+'\nUnmodified masters preserved alongside the cropped production WAVs.\n')
print(json.dumps({'generated':str(generated),'clips':manifest['items']},indent=2))
